// One X post per published item: title, a short hook, the link. X counts any link as 23 characters; the limit is 280.
const input = $input.first().json;
const d = input.body || input;
const clean = (t) => String(t || '').replace(/\s+/g, ' ').trim();
const url = clean(d.url);
if (!/^https:\/\/your-blog\.example\//.test(url)) throw new Error('X post refused: the link is not on your-blog.example');
const title = clean(d.title).slice(0, 150);
if (!title) throw new Error('X post refused: no title');
const head = d.kind === 'digest' ? 'Weekly digest: ' : d.kind === 'ham' ? 'Band conditions: ' : '';
const cut = /(\.{3}|…)$/.test(clean(d.excerpt));                // the blog's excerpt is already cut mid-sentence
let hook = clean(d.excerpt).replace(/(\.{3}|…)$/, '') + (cut ? '…' : '');
const room = 280 - 23 - (head + title).length - 4;          // 4 = the line breaks
if (hook.length > room) { hook = hook.slice(0, Math.max(0, room - 1)); hook = hook.slice(0, hook.lastIndexOf(' ')) + '…'; }
if (room < 40 || hook === '…') hook = '';
const text = head + title + (hook ? '\n\n' + hook : '') + '\n\n' + url;
return [{ json: { text, waitSeconds: Math.min(900, Math.max(0, Number(d.waitSeconds) || 0)) } }];
